class Solution {
public:
    vector<int> sequentialDigits(int low, int high) {
        vector<int> ans;

        string s = "123456789";
        string l = to_string(low);
        string h = to_string(high);

        for(int i = l.size(); i <= h.size(); i++) {
            for(int j = 0; j <= 9 - i; j++) {
                string n = s.substr(j, i);
                int num = stoi(n);
                if(num >= low && num <= high)
                    ans.push_back(num);
            }
        }

        return ans;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> mp;

        for(int i=0;i< nums.size();i++)
        {
            int req = target - nums[i];
            if(mp.find( req)!= mp.end())
            {
                return { mp[req], i};
            }

            mp[nums[i]]=i;
        }
       return {};
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums)
     {
        vector<vector<int>> res;
        sort( nums.begin(), nums.end());
        int n = nums.size();
        for(int i=0;i<n-2;i++)
        {
           if (nums[i] + nums[i + 1] + nums[i + 2] > 0) break; 
           if (nums[i] + nums[n - 2] + nums[n - 1] < 0) continue;

            if( i>0 && nums[i]==nums[i-1]) continue;
            int j=i+1;
            int k= n-1;
            while( j<k)
            {
                int tot=nums[i]+ nums[j]+nums[k];
                if( tot==0)
                {
                    res.push_back({nums[i], nums[j], nums[k]});
                    j++;
                    k--;
                    while( nums[j]==nums[j-1] &&  j<k) j++;
                    while( nums[k]==nums[k+1] && j<k) k--;
                }
                else if( tot> 0) k--;
                else j++;

            }
        }
        
        return res;
    }
};

class Solution {
public:
    int first_oc( vector<int> & nums, int n ,int target)
    {
        int low = 0;
        int high =n-1;
        int ans =-1;
        while( low<=high)
        {
            int mid= low+ ( high-low)/2;
            if( nums[mid]==target)
            {
                ans = mid;
                high =mid-1;
            }
            else if( target> nums[mid]) low= mid+1;
            else high = mid-1;
        }
       return ans;

    }
    int last_oc( vector<int>&nums, int n , int target)
    {
        int low = 0;
        int high = n-1;
        int ans =-1;
        while( low<=high)
        {
            int mid= low+ ( high-low)/2;
            if( nums[mid]==target)
            {
                ans = mid;
                low = mid+1;
            }
            else if( target> nums[mid]) low= mid+1;
            else high = mid-1;
        }
       return ans;
    }
    vector<int> searchRange(vector<int>& nums, int target) {
        int n = nums.size();
        int fo= first_oc(nums,n,target);
        int lo= last_oc(nums,n,target);
        return {fo,lo};
        
        
    }
};
